new:
var encodingOptions = new StackPanel { Spacing = 6 };
encodingOptions.Children.Add(Row(Se.Language.Video.BurnIn.SampleRate, Combo(vm.AudioSampleRates, vm, nameof(vm.SelectedAudioSampleRate), Se.Language.Video.BurnIn.SampleRate)));
encodingOptions.Children.Add(Row(Se.Language.Video.BurnIn.BitRate, Combo(vm.AudioBitRates, vm, nameof(vm.SelectedAudioBitRate), Se.Language.Video.BurnIn.BitRate)));
encodingOptions.Children.Add(EditorChrome.MakeSwitchRow(EditorChrome.MakeSwitch(nameof(vm.AudioIsStereo), Se.Language.General.Stereo), Se.Language.General.Stereo));
var copyNotice = new TextBlock
{
    Text = Se.Settings.General.Language.Contains("Hebrew", System.StringComparison.OrdinalIgnoreCase)
        ? "במצב העתקה, האודיו נשמר ללא קידוד מחדש. הגדרות קצב הנתונים וקצב הדגימה אינן חלות."
        : "Audio copy preserves the audio without re-encoding. Bitrate and sample rate settings do not apply.",
    TextWrapping = TextWrapping.Wrap,
    MaxWidth = 440,
};
void RefreshAudioOptions()
{
    var copying = vm.SelectedAudioEncoding == "copy";
    encodingOptions.IsEnabled = !copying;
    copyNotice.IsVisible = copying;
}
System.ComponentModel.PropertyChangedEventHandler changed = (_, e) =>
{
    if (e.PropertyName == nameof(vm.SelectedAudioEncoding)) RefreshAudioOptions();
};
rows.AttachedToVisualTree += (_, _) => { vm.PropertyChanged += changed; RefreshAudioOptions(); };
rows.DetachedFromVisualTree += (_, _) => vm.PropertyChanged -= changed;
RefreshAudioOptions();
rows.Children.Add(encodingOptions);
rows.Children.Add(copyNotice);
